  s += `<polygon points="${pts(right)}" fill="url(#rf)" stroke="${col}" stroke-opacity=".35" stroke-width=".6"/>`;
  for (let z = 10; z < h - 4; z += 9) s += `<polyline points="${pts([lf(g, 0, z), lf(g, 1, z), rf(g, 1, z)])}" fill="none" stroke="${col}" stroke-opacity=".07" stroke-width=".5"/>`;
