  s += `<line x1="${g.x}" y1="${g.y - h}" x2="${g.x}" y2="${g.y - h - 13}" stroke="${col}" stroke-width=".8" stroke-opacity=".8"/>`;
  s += `<circle cx="${g.x}" cy="${g.y - h - 13}" r="1.6" fill="${col}"/>`;
