// ------------------------------------------------------------------ inside a building: the workers and what they process
// Tap a building in the Live view: the tower opens floor by floor. Every room is one desk: documents arrive in the inbox
// (coloured by the company that wrote them), the worker processes them, a hologram shows a small animated chart of the
// real numbers on that desk right now, and the results leave through the outbox toward the companies that read them.
const ORDER = ["wire", "exchange", "lab", "sim", "ourbook", "news", "trading", "audit", "ops", "front"];
let inside = null, actTimer = null, actN = 0, nowTimer = null, nowN = 0;
